#' Render a parsed Rd topic as a Markdown string
#'
#' Produces the full contents of a single function's `.md` file, following
#' the output format defined in `CLAUDE.md` (title line, arguments table,
#' return value, collapsible examples, related functions, footer). Both the
#' R code (comments, roxygen docs) and the rendered Markdown output are in
#' English, per project convention.
#'
#' @param topic A parsed topic list, as produced by `.parse_rd_topic()`.
#' @param version Version string of the documented package.
#' @param footer Whether to append the "Generated by" footer with its
#'   relative links. Set to `FALSE` when concatenating many topics into
#'   `_full_reference.md`, where per-topic footers would repeat the same
#'   boilerplate dozens of times and the relative links don't resolve
#'   usefully anyway.
#' @return A single Markdown string (the complete file contents).
#' @keywords internal
.render_topic_md <- function(topic, version, footer = TRUE) {
  return(glue::glue(
    "# {.render_topic_heading(topic)} \u2014 {topic$title}{.render_private_badge(topic)}\n\n",
    "**Package:** {topic$package} \u00b7 **Version:** {version}\n\n",
    "{.render_aliases_line(topic)}",
    "{.render_description_section(topic)}",
    "{.render_usage_section(topic)}",
    "{.render_arguments_section(topic)}",
    "{.render_details_section(topic)}",
    "{.render_sections(topic)}",
    "{.render_format_section(topic)}",
    "{.render_value_section(topic)}",
    "{.render_examples_section(topic)}",
    "{.render_seealso_section(topic)}",
    "{.render_note_section(topic)}",
    "{.render_source_section(topic)}",
    "{.render_references_section(topic)}",
    "{.render_author_section(topic)}",
    "{if (footer) '---\n*Generated by [csdocs](https://github.com/niphr/csdocs) \u00b7 [Back to index](README.md)*\n' else ''}",
    .trim = FALSE
  ))
}

#' Determine which of a topic's name/aliases are actually callable
#'
#' A topic is "callable" for heading purposes if its own name (or one of
#' its aliases) literally appears followed by `(` in its `\\usage{}` block
#' - e.g. `mutate.Rd` has usage `mutate(.data, ...)`, so `"mutate"`
#' qualifies. Datasets and concept pages (`\\usage{}` is just a bare name,
#' or empty) never qualify. A single Rd topic can document several
#' callables at once (e.g. `lead-lag.Rd` documents both `lead()` and
#' `lag()`, with topic name `"lead-lag"` matching neither) - hence this
#' returns a vector, not a single yes/no.
#'
#' @param topic Parsed topic list.
#' @return Character vector of callable names (possibly empty).
#' @keywords internal
.callable_names <- function(topic) {
  return(.callable_candidates(topic$name, topic$aliases, topic$usage))
}

#' Render a topic's heading identifier (the part before " - Title")
#'
#' Renders callable names as `` `name()` `` (joined with a middle dot when a
#' topic documents more than one, e.g. `lead()` / `lag()`), or the bare
#' topic name with no parentheses for non-callable topics (datasets,
#' concept/package-overview pages) - see [.callable_names()].
#'
#' @param topic Parsed topic list.
#' @return A Markdown string fragment.
#' @keywords internal
.render_topic_heading <- function(topic) {
  callable <- .callable_names(topic)
  if (length(callable) == 0) {
    return(.inline_code_span(topic$name))
  }
  return(paste(
    purrr::map_chr(callable, \(name) .inline_code_span(paste0(name, "()"))),
    collapse = " \u00b7 "
  ))
}

#' Render a `_(private)_` marker for topics outside the public API
#'
#' @param topic Parsed topic list.
#' @return `" _(private)_"`, or `""` if `topic$is_private` isn't `TRUE`.
#' @keywords internal
.render_private_badge <- function(topic) {
  if (isTRUE(topic$is_private)) return(" _(private)_") else return("")
}

#' Render a compact "Aliases:" line for aliases not already in the heading
#'
#' `topic$aliases` commonly includes the topic's own name plus every name
#' already surfaced via [.render_topic_heading()] (e.g. S3 method aliases,
#' or the callable names of a multi-function topic) - repeating those here
#' would be redundant. Only genuinely additional aliases are listed, so
#' e.g. `lag()` stays findable even though the topic file itself is named
#' `lead-lag.md`.
#'
#' @param topic Parsed topic list.
#' @return Markdown string, possibly empty.
#' @keywords internal
.render_aliases_line <- function(topic) {
  extra <- setdiff(
    topic$aliases %||% character(0),
    c(topic$name, .callable_names(topic))
  )
  if (length(extra) == 0) {
    return("")
  }
  labels <- paste(purrr::map_chr(extra, .inline_code_span), collapse = ", ")
  return(glue::glue("**Aliases:** {labels}\n\n", .trim = FALSE))
}

#' Render the description section, if present
#' @param topic Parsed topic list.
#' @return Markdown string, possibly empty.
#' @keywords internal
.render_description_section <- function(topic) {
  description <- topic$description %||% ""
  if (identical(description, "")) {
    return("")
  }
  return(glue::glue("{description}\n\n", .trim = FALSE))
}

#' Render the usage section, if present
#' @param topic Parsed topic list.
#' @return Markdown string, possibly empty.
#' @keywords internal
.render_usage_section <- function(topic) {
  usage <- topic$usage %||% ""
  if (identical(usage, "")) {
    return("")
  }
  fence <- .code_fence(usage)
  return(glue::glue(
    "## Usage\n\n{fence}r\n{usage}\n{fence}\n\n",
    .trim = FALSE
  ))
}

#' Render the arguments table, if present
#'
#' Cell content is escaped via [.escape_table_pipe()] - argument
#' descriptions are free-form prose that may legitimately contain a
#' literal `|` (e.g. "TRUE or FALSE"), which would otherwise terminate the
#' cell early and break the rest of the table.
#'
#' @param topic Parsed topic list.
#' @return Markdown string, possibly empty.
#' @keywords internal
.render_arguments_section <- function(topic) {
  if (length(topic$arguments) == 0) {
    return("")
  }

  rows <- purrr::map_chr(topic$arguments, \(arg) {
    name <- .inline_code_span(.escape_table_pipe(arg$name))
    description <- .escape_table_pipe(arg$description)
    return(glue::glue("| {name} | {description} |"))
  })

  return(glue::glue(
    "## Arguments\n\n",
    "| Argument | Description |\n",
    "|----------|-------------|\n",
    "{paste(rows, collapse = '\n')}\n\n",
    .trim = FALSE
  ))
}

#' Render the details section, if present
#'
#' `topic$details` is already multi-paragraph Markdown produced by
#' [.rd_to_block_md()] (lists, subsections, code blocks may all be
#' present), so it's interpolated as-is rather than wrapped as a single
#' line.
#'
#' @param topic Parsed topic list.
#' @return Markdown string, possibly empty.
#' @keywords internal
.render_details_section <- function(topic) {
  details <- topic$details %||% ""
  if (identical(details, "")) {
    return("")
  }
  return(glue::glue("## Details\n\n{details}\n\n", .trim = FALSE))
}

#' Render every `\\section{title}{body}` block, if any
#'
#' A topic can have any number of these (see [.parse_rd_sections()]), each
#' with its own title - e.g. dplyr's `mutate.Rd` has "Useful mutate
#' functions", "Grouped tibbles", and "Methods". Each renders as its own
#' `## Title` heading, in source order.
#'
#' @param topic Parsed topic list.
#' @return Markdown string, possibly empty.
#' @keywords internal
.render_sections <- function(topic) {
  sections <- topic$sections %||% list()
  if (length(sections) == 0) {
    return("")
  }
  chunks <- purrr::map_chr(sections, \(section) {
    return(glue::glue(
      "## {section$title}\n\n{section$body}\n\n",
      .trim = FALSE
    ))
  })
  return(paste(chunks, collapse = ""))
}

#' Render the format section, if present
#'
#' `\\format{}` is where dataset topics (e.g. `starwars`, `storms`)
#' describe their variables - almost always via `\\describe{}`, handled as
#' Tier 3 Markdown like `\\details{}`.
#'
#' @param topic Parsed topic list.
#' @return Markdown string, possibly empty.
#' @keywords internal
.render_format_section <- function(topic) {
  format <- topic$format %||% ""
  if (identical(format, "")) {
    return("")
  }
  return(glue::glue("## Format\n\n{format}\n\n", .trim = FALSE))
}

