#' Render the examples section as a `<details>` block, if present
#' @param topic Parsed topic list.
#' @return Markdown string, possibly empty.
#' @keywords internal
.render_examples_section <- function(topic) {
  examples <- topic$examples %||% ""
  if (identical(examples, "")) {
    return("")
  }
  fence <- .code_fence(examples)
  return(glue::glue(
    "## Examples\n\n",
    "<details>\n",
    "<summary>Show examples</summary>\n\n",
    "{fence}r\n{examples}\n{fence}\n\n",
    "</details>\n\n",
    .trim = FALSE
  ))
}

